chart.options:
chart: {
  type: 'dumbbell',
  height: 380
},
colors: ['#F59E0B', '#0EA5E9'],
plotOptions: {
  bar: {
    horizontal: false
  }
},
title: {
  text: 'Daily temperature range by month',
  align: 'left'
},
subtitle: {
  text: 'Illustrative data, degrees Celsius',
  align: 'left'
},
yaxis: {
  labels: {
    formatter: function (val) {
      return Math.round(val) + '°'
    }
  }
}
